import {PHET_MODELS} from './phet-models.mjs';
// SI units unless a field explicitly states otherwise. Presentation time can be slowed.
export const g=9.81,K=8.9875517923e9,R=8.314462618;
export const rad=d=>d*Math.PI/180;
export function projectile(p,t=0){const vx=p.speed*Math.cos(rad(p.angle)),vy0=p.speed*Math.sin(rad(p.angle)),flight=(vy0+Math.sqrt(vy0**2+2*p.gravity*p.height))/p.gravity;const time=Math.min(t,flight);return {flight,range:vx*flight,peak:p.height+vy0**2/(2*p.gravity),x:vx*time,y:Math.max(0,p.height+vy0*time-.5*p.gravity*time**2),vx,vy:vy0-p.gravity*time,time};}
export function incline(p,t=0){const normal=p.mass*g*Math.cos(rad(p.angle)),down=p.mass*g*Math.sin(rad(p.angle)),friction=Math.min(down,p.mu*normal),a=(down-friction)/p.mass,time=a>1e-12?Math.min(t,Math.sqrt(10/a)):0;return {normal,friction,a,x:.5*a*time**2,v:a*time,time,flight:a>1e-12?Math.sqrt(10/a):0};}
export function spring(p,t=0){const omega=Math.sqrt(p.k/p.mass),x=p.amplitude*Math.cos(omega*t),v=-p.amplitude*omega*Math.sin(omega*t);return {omega,period:2*Math.PI/omega,x,v,kinetic:.5*p.mass*v*v,potential:.5*p.k*x*x,energy:.5*p.k*p.amplitude**2,time:t};}
export function collision(p,t=0){const total=p.m1+p.m2,v1=(p.m1*p.v1+p.m2*p.v2-p.m2*p.e*(p.v1-p.v2))/total,v2=(p.m1*p.v1+p.m2*p.v2+p.m1*p.e*(p.v1-p.v2))/total,tc=3.4/(p.v1-p.v2),xc=-2+p.v1*tc,hit=t>=tc;return {tc,v1:hit?v1:p.v1,v2:hit?v2:p.v2,x1:hit?xc+v1*(t-tc):-2+p.v1*t,x2:hit?xc+.6+v2*(t-tc):2+p.v2*t,momentum:p.m1*p.v1+p.m2*p.v2,energy:hit?.5*(p.m1*v1*v1+p.m2*v2*v2):.5*(p.m1*p.v1**2+p.m2*p.v2**2),loss:hit?.5*p.m1*p.m2/total*(1-p.e**2)*(p.v1-p.v2)**2:0,hit,time:t};}
export function circular(p,t=0){return {omega:p.speed/p.radius,period:2*Math.PI*p.radius/p.speed,a:p.speed**2/p.radius,force:p.mass*p.speed**2/p.radius,x:p.radius*Math.cos(p.speed*t/p.radius),y:p.radius*Math.sin(p.speed*t/p.radius),time:t};}
export function buoyancy(p){const weight=p.object*p.volume*g,force=p.fluid*p.volume*p.immersion*g;return {weight,force,net:force-weight,fraction:p.object/p.fluid,mass:p.object*p.volume};}
export function circuit(p){const resistance=p.mode==='series'?p.r1+p.r2:1/(1/p.r1+1/p.r2),current=p.voltage/resistance,i1=p.mode==='series'?current:p.voltage/p.r1,i2=p.mode==='series'?current:p.voltage/p.r2;return {resistance,current,i1,i2,power:p.voltage*current,v1:i1*p.r1,v2:i2*p.r2};}
export function coulomb(p){const signed=K*p.q1*p.q2*1e-12/p.distance**2;return {force:Math.abs(signed),signed,potential:K*p.q1*p.q2*1e-12/p.distance};}
export function magnetic(p,t=0){const charge=p.particle==='electron'?-1.602176634e-19:1.602176634e-19,mass=p.particle==='electron'?9.1093837139e-31:1.67262192595e-27,speed=p.speed*1000,B=p.field*.001,omega=Math.abs(charge)*B/mass,radius=speed/omega,period=2*Math.PI/omega,phase=omega*t;return {charge,mass,speed,B,omega,radius,period,force:Math.abs(charge)*speed*B,x:radius*Math.sin(phase),y:Math.sign(charge)*radius*(Math.cos(phase)-1),energy:.5*mass*speed**2,time:t};}
export function induction(p,t=0){const omega=2*Math.PI*p.frequency,B=p.field*Math.cos(omega*t),flux=p.area*B,emf=p.turns*p.area*p.field*omega*Math.sin(omega*t);return {B,flux,emf,current:emf/p.resistance,peak:p.turns*p.area*p.field*omega,time:t};}
export function lens(p){const f=p.type==='converging'?p.focal:-p.focal,den=p.distance-f;if(Math.abs(den)<1e-10)return {f,image:null,magnification:null,height:null};const image=f*p.distance/den,magnification=-image/p.distance;return {f,image,magnification,height:magnification*6};}
export function refraction(p){const ratio=p.n1/p.n2*Math.sin(rad(p.angle)),tir=ratio>1,angle=tir?null:Math.asin(Math.min(1,ratio))*180/Math.PI,critical=p.n1>p.n2?Math.asin(p.n2/p.n1)*180/Math.PI:null;return {angle,tir,critical,reflected:p.angle};}
export function gas(p){return {pressure:p.moles*R*p.temperature/(p.volume*.001),rms:Math.sqrt(3*R*p.temperature/.039948),energy:1.5*p.moles*R*p.temperature};}
export function heat(p,t=0){const c1=p.m1*385,c2=p.m2*385,equilibrium=(c1*p.t1+c2*p.t2)/(c1+c2),difference=(p.t1-p.t2)*Math.exp(-p.conductance*(1/c1+1/c2)*t),t1=equilibrium+c2/(c1+c2)*difference,t2=equilibrium-c1/(c1+c2)*difference;return {t1,t2,equilibrium,flow:p.conductance*(t1-t2),transferred:c1*(p.t1-t1),energy:c1*t1+c2*t2,time:t};}
export function standing(p,t=0){const speed=Math.sqrt(p.tension/p.density),frequency=p.mode*speed/(2*p.length);return {speed,frequency,nodes:p.mode-1,period:1/frequency,time:t,displacement:x=>p.amplitude*Math.sin(p.mode*Math.PI*x/p.length)*Math.cos(2*Math.PI*frequency*t)};}
export const MODELS={...PHET_MODELS,projectile,incline,spring,collision,circular,buoyancy,circuit,coulomb,magnetic,induction,lens,refraction,gas,heat,standing};
